// Writes <task>/api.d.ts: the TypeScript API the model saw, generated by
// @cloudflare/codemode 0.5.5's generateTypesFromJsonSchema (vendored in
// executor/vendor, needs executor/node_modules for acorn) and scoped per
// provider namespace exactly as executor/providers.ts prepareProviders does.
// The tools have no outputSchema, so codemode types outputs as `unknown`; the
// outputDescription is appended to the tool description, which codemode puts
// in the JSDoc the model reads.
//
//   node bench/v1/tasks/gen-types.ts [task-id...]
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { generateTypesFromJsonSchema } from '../../../executor/vendor/codemode.mjs';
import { readTask, TASKS, type TaskSpec, taskIds } from './lib/tasks.ts';

export function apiTypes(task: TaskSpec): string {
  const out: string[] = [];
  for (const provider of task.providers) {
    const schemas: Record<string, unknown> = {};
    for (const [name, tool] of Object.entries(provider.tools)) {
      const description = tool.outputDescription
        ? tool.description + '\nReturns: ' + tool.outputDescription
        : tool.description;
      schemas[name] = { description, inputSchema: tool.inputSchema };
    }
    const generated = generateTypesFromJsonSchema(schemas).replace('declare const codemode', 'const api');
    out.push(
      `declare namespace __schema_${provider.name} {\n${generated}\n}\ndeclare const ${provider.name}: typeof __schema_${provider.name}.api;`,
    );
  }
  return out.join('\n\n') + '\n';
}

const ids = process.argv.length > 2 ? process.argv.slice(2) : taskIds();
for (const id of ids) {
  const task = readTask(id);
  if (task.kind === 'sql') continue;
  writeFileSync(join(TASKS, id, 'api.d.ts'), apiTypes(task));
  console.log('wrote', id + '/api.d.ts');
}
